'use client';

import Image from 'next/image';
import { useCallback, useEffect, useState } from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import styles from './portfolio-carousel.module.css';

interface Slide {
  label: string;
  labelVariant: string;
  cardVariant: string;
  imageOuterVariant: string;
  imageSrc: string;
  imageAlt: string;
  imageWidth: number;
  imageHeight: number;
}

const SLIDES: Slide[] = [
  {
    label: 'Shopify',
    labelVariant: 'heading-3-green',
    cardVariant: 'cream',
    imageOuterVariant: 'green',
    imageSrc: '/images/webflow/69662a202a4c0d57bdf2c10b_Home.png',
    imageAlt: 'Portfolio Image',
    imageWidth: 843,
    imageHeight: 690,
  },
  {
    label: 'WordPress',
    labelVariant: 'heading-3-green-light',
    cardVariant: 'light-green',
    imageOuterVariant: 'green-light',
    imageSrc: '/images/webflow/Travel.png',
    imageAlt: 'TravelPerk corporate travel management website template built by Boldteq',
    imageWidth: 840,
    imageHeight: 690,
  },
  {
    label: 'Figma UI/UX Design',
    labelVariant: 'heading-3-purple',
    cardVariant: 'light-purple',
    imageOuterVariant: 'orange-light',
    imageSrc: '/images/webflow/Home-1.png',
    imageAlt: 'Dynamic lifestyle brand website template built by Boldteq',
    imageWidth: 843,
    imageHeight: 690,
  },
  {
    label: 'Banners',
    labelVariant: 'heading-3-orange',
    cardVariant: 'light-orange',
    imageOuterVariant: 'olive-green',
    imageSrc: '/images/webflow/Group-7.png',
    imageAlt: 'Beauty and skincare product website template built by Boldteq',
    imageWidth: 807,
    imageHeight: 690,
  },
];

// Duplicate for seamless loop
const ALL_SLIDES = [...SLIDES, ...SLIDES];

export function PortfolioCarousel() {
  const [emblaRef, emblaApi] = useEmblaCarousel({
    loop: true,
    align: 'start',
    dragFree: false,
    slidesToScroll: 1,
  });
  const [selectedIndex, setSelectedIndex] = useState(0);

  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
  const scrollTo = useCallback((i: number) => emblaApi?.scrollTo(i), [emblaApi]);

  useEffect(() => {
    if (!emblaApi) return;
    const onSelect = () => setSelectedIndex(emblaApi.selectedScrollSnap() % SLIDES.length);
    emblaApi.on('select', onSelect);
    onSelect();
    return () => { emblaApi.off('select', onSelect); };
  }, [emblaApi]);

  return (
    <section
      className={`${styles['section-regular-2']} ${styles['img-slider-sec']}`}
    >
      <div className={styles['column-4x-large']} style={{ alignItems: 'center' }}>
        {/* Slider container — relative for arrow positioning */}
        <div style={{ position: 'relative', width: '100%' }}>
          {/* Embla viewport */}
          <div ref={emblaRef} className={styles['gallery-13-mask']}>
            {/* Track */}
            <div style={{ display: 'flex', gap: '24px', height: 'auto' }}>
              {ALL_SLIDES.map((slide, i) => (
                <div
                  key={`${slide.label}-${i}`}
                  className={styles['gallery-13-slide']}
                >
                  <div
                    className={`${styles['gallery-13-card']} ${styles[slide.cardVariant]}`}
                  >
                    {/* Image outer */}
                    <div
                      className={`${styles['gallery-image-outer']} ${styles[slide.imageOuterVariant]}`}
                    >
                      <Image
                        src={slide.imageSrc}
                        alt={slide.imageAlt}
                        width={slide.imageWidth}
                        height={slide.imageHeight}
                        loading="lazy"
                        className={`${styles['image-cover']} ${styles['radius-0']}`}
                      />
                    </div>
                    {/* Caption */}
                    <div className={styles['gallery-13-caption']}>
                      <div className={`${styles['heading-3']} ${styles[slide.labelVariant]}`}>
                        {slide.label}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Prev button */}
          <button
            onClick={scrollPrev}
            aria-label="Previous slide"
            className={`${styles['gallery-13-button']} ${styles['button-left']}`}
            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
          >
            <div className={styles['icon-button-outline-large']}>
              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M7.82843 10.9999H20V12.9999H7.82843L13.1924 18.3638L11.7782 19.778L4 11.9999L11.7782 4.22168L13.1924 5.63589L7.82843 10.9999Z" fill="currentColor" />
                </svg>
              </span>
            </div>
          </button>

          {/* Next button */}
          <button
            onClick={scrollNext}
            aria-label="Next slide"
            className={`${styles['gallery-13-button']} ${styles['button-right']}`}
            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
          >
            <div className={styles['icon-button-outline-large']}>
              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M16.1716 10.9999L10.8076 5.63589L12.2218 4.22168L20 11.9999L12.2218 19.778L10.8076 18.3638L16.1716 12.9999H4V10.9999H16.1716Z" fill="currentColor" />
                </svg>
              </span>
            </div>
          </button>
        </div>

        {/* Dot navigation */}
        <div
          style={{
            justifyContent: 'flex-start',
            alignItems: 'center',
            maxWidth: 'calc(100% - 112px)',
            marginLeft: 0,
            paddingTop: '16px',
            paddingBottom: '16px',
            display: 'flex',
            gap: '4px',
          }}
        >
          {SLIDES.map((_, i) => (
            <button
              key={i}
              onClick={() => scrollTo(i)}
              aria-label={`Go to slide ${i + 1}`}
              style={{
                height: '12px',
                width: '12px',
                borderRadius: '50%',
                border: 'none',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
                backgroundColor: i === selectedIndex ? '#000' : '#EDF0F2',
                marginBottom: 0,
                padding: 0,
                flexShrink: 0,
              }}
            />
          ))}
        </div>
      </div>

      <div className={styles['container-large-2']} />
    </section>
  );
}

import Image from 'next/image';
import styles from './pain-points.module.css';

const CARDS = [
  {
    title: 'Bottlenecked Delivery',
    description:
      "Your team is stretched thin. Projects move slower, timelines slip, and you're forced to turn down work you should be able to take on.",
    imageSrc: '/images/webflow/Group-46945.png',
    imageAlt: 'Project overview',
    imageWidth: 1492,
    imageHeight: 800,
    sizes: '(max-width: 1492px) 100vw, 1492px',
  },
  {
    title: 'Unreliable Outsourcing',
    description:
      'Freelancers and vendors deliver inconsistent quality, miss deadlines, or require constant follow-ups \u2014 putting your brand reputation and client trust at risk.',
    imageSrc: '/images/webflow/Group-46953.png',
    imageAlt: 'Unreliable outsourcing',
    imageWidth: 1492,
    imageHeight: 800,
    sizes: '(max-width: 1492px) 100vw, 1492px',
  },
  {
    title: 'High Hiring Costs',
    description:
      'Scaling through full-time hires means salaries, onboarding, tools, and long ramp-up times \u2014 all before you see real ROI.',
    imageSrc: '/images/webflow/Group-46951.png',
    imageAlt: 'High Hiring cost',
    imageWidth: 1492,
    imageHeight: 800,
    sizes: '(max-width: 1492px) 100vw, 1492px',
  },
] as const;

export function PainPoints() {
  return (
    <section
      className={`${styles['section-regular-3']} ${styles['slowing-sec']}`}
    >
      <div className={styles['container-large-3']}>
        <h2 className={`${styles['heading-2']} ${styles['margin-bottom-24px']}`}>
          What&apos;s Slowing Your Agency Down?
        </h2>
        <p className={`${styles['paragraph']} ${styles['center']}`}>
          Running an agency shouldn&apos;t feel like constant firefighting. Yet most growing agencies hit
          <br />
          the same roadblocks that quietly slow delivery, limit capacity, and hurt margins.
        </p>

        <div
          className={`${styles['feature-grid']} ${styles['margin-top-40px']} ${styles['agency-grid']}`}
          style={{ display: 'grid' }}
        >
          {CARDS.map((card) => (
            <a
              key={card.title}
              href="#"
              className={styles['feature-card']}
            >
              <div className={`${styles['text-wrapper']} ${styles['featured-card-twrapper']}`}>
                <div className={`${styles['subheading-large']} ${styles['margin-bottom-5']}`}>
                  <strong>{card.title}</strong>
                </div>
                <p className={`${styles['paragraph-small-2']} ${styles['margin-bottom-20px']}`}>
                  {card.description}
                </p>
              </div>
              <Image
                src={card.imageSrc}
                loading="lazy"
                width={card.imageWidth}
                height={card.imageHeight}
                alt={card.imageAlt}
                sizes={card.sizes}
                className={`${styles['full-width-image']} ${styles['drop-shadow']}`}
              />
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}

