/* ============================================================
   HERO — hero.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-high-judge {
  background-color: #0000;
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 100%, 0 0;
  background-repeat: repeat, repeat;
  background-size: cover, auto;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.home-ban-judge {
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 0, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: cover, auto;
}

.div-white-bag {
  position: relative;
  overflow-x: hidden;
}

.div-stuck-swept {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
  font-weight: 400;
  text-decoration: none;
}

.div-wrote-smoke {
  text-align: center;
  color: #05bafe;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
  padding: 0;
  font-weight: 400;
  text-decoration: none;
}

.review-link {
  text-decoration: none;
}

.review-stars {
  background-color: #00b67a1a;
  border-radius: 10px;
  padding: 8px 10px;
}

.p-base-place {
  color: #092245;
  margin-top: 1.5rem;
  margin-bottom: 0;
  padding: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

.animate-span {
  color: #05bafe;
}

.p-base-place-copy {
  color: #092245;
  margin-top: 0;
  margin-bottom: 10px;
  padding: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

.h1-season-seeing {
  color: #2b2b2b;
  max-width: 52rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  text-decoration: none;
}

.div-job-attention {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
  position: relative;
}

.mob-left {
  /* applied at mobile only — see media query below */
}

.mob-margin-less {
  margin-top: 1rem;
}

.ban-grid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 0.75fr 0.85fr;
  grid-auto-columns: 1fr;
  max-width: 660px;
  margin-bottom: 50px;
  display: grid;
}

.margin-bottom-0 {
  margin-bottom: 0;
}

.hom-ban-grd {
  /* additional modifier — used with ban-grid.margin-bottom-0 */
}

.grid-box {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  padding: 20px;
  transition: all 0.5s;
  display: flex;
  box-shadow: 0 0 5px #0000001a;
}

.home-grid-box {
  padding-top: 13px;
  padding-bottom: 13px;
}

.home-bangrid-icon {
  /* base size — width is set by Webflow defaults */
}

.grid-para {
  color: #000;
  text-align: left;
  max-width: none;
  margin-bottom: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
}

.mob-center {
  color: #082753;
  font-size: 15px;
}

.lighter-font {
  font-size: 15px;
}

/* Badge 2 "No Contract" max-width constraint (.grid-para.middle) */
.middle {
  max-width: 80px;
}

.code-embed-3 {
  margin-top: 15px;
  margin-bottom: 80px;
}

.how-code-embed {
  margin-top: 30px;
}

.margin-top-50 {
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  margin: 50px auto 40px;
  box-shadow: 0 0 5px #0000001a;
}

.a-gulf-book {
  color: #fff;
  width: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--button-text, 1rem);
  background-color: #111827;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid #0000;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: 0 0 5px #0000001a;
}

.a-gulf-book:hover {
  background-color: #092245;
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

.a-except-get {
  color: #111827;
  width: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--button-text, 1rem);
  background-color: #21cfff21;
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border: 2px solid #9ca3af;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-top: 0;
  margin-left: 1.25rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: 0 0 5px #0000001a;
}

.a-except-get:hover {
  color: #fff;
  background-color: #092245;
  border-color: #111827;
}

.gradient-bg-ban {
  background-image: linear-gradient(#fff0, #fff);
  height: 170px;
  position: absolute;
  inset: auto 0% 0%;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .section-high-judge {
    background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
    background-position: 50% 100%, 0 0;
    background-repeat: repeat, repeat;
    background-size: cover, auto;
    padding-top: 4rem;
    padding-bottom: 4rem;
  }

  .div-stuck-swept {
    padding-left: 2rem;
    padding-right: 2rem;
  }

  .p-base-place {
    color: #092245;
    font-size: 50px;
    line-height: 1.25;
  }

  .div-job-attention {
    justify-content: center;
    align-items: center;
    margin-top: 2rem;
    padding-left: 0;
    padding-right: 0;
    display: flex;
  }

  .a-gulf-book {
    background-image: url('/images/webflow/Group-46729.svg'), linear-gradient(90deg, #21cfff, #019ae6);
    background-position: 93%, 0 0;
    background-repeat: no-repeat, repeat;
    background-size: auto, auto;
    border-style: none;
    width: auto;
    padding-left: 1.25rem;
    padding-right: 3rem;
  }

  .a-gulf-book:hover {
    background-image: url('/images/webflow/Group-46729-2.svg');
  }

  .a-except-get {
    background-color: #21cfff21;
    background-image: url('/images/webflow/Group-46729-1.svg');
    background-position: 94%;
    background-repeat: no-repeat;
    background-size: auto;
    border-style: none;
    width: auto;
    margin-top: 0;
    margin-left: 1.25rem;
    padding-left: 1.25rem;
    padding-right: 3rem;
  }

  .ban-grid {
    grid-template-rows: auto;
    grid-template-columns: 1fr 1fr 1fr;
    max-width: 700px;
    margin-bottom: 50px;
  }

  .ban-grid.margin-bottom-0 {
    grid-template-columns: 1fr 0.65fr 0.75fr;
    max-width: 650px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section-high-judge {
    background-color: #fff;
    background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
