    width: auto;
  }

  .a-gulf-book:hover {
    background-image: url('/images/webflow/Group-46729-2.svg');
  }

  .a-except-get {
    background-color: #21cfff21;
    width: auto;
    margin-top: 0;
    margin-left: 1.25rem;
  }

  .ban-grid.margin-bottom-0 {
    grid-template-columns: 1fr 0.65fr 0.75fr;
    max-width: 640px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .h1-season-seeing {
    color: #2b2b2b;
    margin-top: 10px;
  }

  .ban-grid {
    margin-bottom: 50px;
  }

  .ban-grid.margin-bottom-0 {
    grid-template-columns: 1fr 0.65fr 0.75fr;
    max-width: 650px;
  }
}

/* ============================================================
