/* ============================================================
   PAIN POINTS — pain-points.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-regular-3 {
  -webkit-text-fill-color: inherit;
  background-color: #0000;
  background-clip: border-box;
  padding: 0 5% 80px;
  position: relative;
}

.slowing-sec {
  padding-bottom: 30px;
}

.container-large-3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

.heading-2 {
  color: var(--blue, #082753);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--h2, 40px);
  text-align: center;
  line-height: 40px;
}

.margin-bottom-24px {
  margin-bottom: 20px;
  font-size: 40px;
  line-height: 45px;
}

.paragraph {
  color: #2b2b2b;
  text-align: center;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
}

.center {
  text-align: center;
}

/* Base: 3-column grid */
.feature-grid {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  display: grid;
}

/* margin-top-40px modifier preserves 3-col layout and adds margin */
.margin-top-40px {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  margin-top: 40px;
}

.agency-grid {
  /* no additional base rules — modifier class */
}

.feature-card {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  text-align: center;
  mix-blend-mode: normal;
  background-color: #def4ff;
  background-image: none;
  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: flex-start;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.text-wrapper {
  /* wrapper for text content inside feature card */
}

.featured-card-twrapper {
  /* modifier — no extra base CSS in Webflow source */
}

.subheading-large {
  color: #082753;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

.margin-bottom-5 {
  color: #082753;
  margin-bottom: 5px;
  font-size: 22px;
  line-height: 35px;
}

.paragraph-small-2 {
  color: #2b2b2b;
  min-height: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--para-small, 16px);
  letter-spacing: -0.08px;
  margin-bottom: 0;
  line-height: 24px;
}

.margin-bottom-20px {
  color: #2b2b2b;
  margin-bottom: 20px;
  font-size: 16px;
  line-height: 28px;
}

.full-width-image {
  width: 100%;
  max-width: 3768px;
}

.drop-shadow {
  max-width: 1492px;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .container-large-3,
  .container-large-3.full-width {
    max-width: 1280px;
  }

  .feature-card {
    background-color: #def4ff;
    border-color: #009ce0;
  }

  .feature-card.space-between {
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section-regular-3.center-sec {
    padding-bottom: 0%;
  }

  .container-large-3 {
    max-width: 1280px;
  }
}

/* ============================================================
   max-width: 991px
   —
   Webflow rule (line 24558–24564):
     .feature-grid           → grid-template-columns: 1fr
     .feature-grid.margin-top-40px → grid-template-columns: 1fr 1fr 1fr
   Pain Points uses BOTH classes, so the 3-col override applies.
   ============================================================ */
@media screen and (max-width: 991px) {
  /* Generic feature-grid collapses to 1-col */
  .feature-grid {
    grid-template-columns: 1fr;
  }

  /* But feature-grid WITH margin-top-40px stays 3-col (Pain Points uses this) */
  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .section-regular-3 {
    padding-bottom: 0;
  }

  .heading-2.margin-bottom-24px {
    margin-top: 0;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section-regular-3 {
    padding-top: 0;
    padding-bottom: 0;
  }

  /* .slowing-sec modifier restores 30px bottom padding even though base collapses to 0 */
  .section-regular-3.slowing-sec {
    padding-bottom: 30px;
  }

  .heading-2 {
    font-size: 34px;
  }

  .heading-2.margin-bottom-24px {
    font-size: 35px;
    line-height: 45px;
  }

  /* At 767px, margin-top-40px collapses to 1-col (Webflow line 27051) */
  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section-regular-3 {
    padding-top: 0;
    padding-bottom: 40px;
  }

  /* Webflow .section-regular-3.slowing-sec sets padding-bottom: 30px at 479px */
  .section-regular-3.slowing-sec {
    padding-bottom: 30px;
  }

  .heading-2.margin-bottom-24px {
    text-align: center;
    margin-bottom: 10px;
    font-size: 23px;
    line-height: 28px;
  }

  .paragraph.center {
    text-align: center;
  }

  .paragraph-small-2.margin-bottom-20px,
  .subheading-large,
  .subheading-large.margin-bottom-5 {
    text-align: center;
  }

  .feature-card {
    padding: 24px;
  }
}

